import { cn } from "@/lib/utils"

interface Feature {
  title: string
  description: string
  icon: string
}

const FEATURES: Feature[] = [
  {
    icon: "🔐",
    title: "Authentication built-in",
    description:
      "NextAuth v5 with email/password, email verification, and role-based access control (RBAC) out of the box.",
  },
  {
    icon: "💳",
    title: "Billing-ready",
    description:
      "PaymentProvider abstraction supports Stripe and ECPay. Swap gateways without touching your app logic.",
  },
  {
    icon: "🗄️",
    title: "Database with Drizzle",
    description:
      "Type-safe Drizzle ORM on PostgreSQL. Migrations, seeding, and schema fragments — all included.",
  },
  {
    icon: "🎨",
    title: "Dark mode & theming",
    description:
      "Tailwind v4 + next-themes + shadcn/ui. Class-strategy dark mode toggles with a single keypress.",
  },
  {
    icon: "🧩",
    title: "Registry modules",
    description:
      "Install features via `npx shadcn@latest add @saas/<module>`. Each module ships with a manifest and install skill.",
  },
  {
    icon: "🚀",
    title: "Deploy anywhere",
    description:
      "Zeabur config included. Single-service Next.js app with a Dockerfile and auto-migrations on start.",
  },
]

interface FeatureCardProps extends Feature {
  className?: string
}

function FeatureCard({ icon, title, description, className }: FeatureCardProps) {
  return (
    <div
      className={cn(
        "flex flex-col gap-3 rounded-lg border bg-card p-6 text-card-foreground shadow-sm",
        className,
      )}
    >
      <span className="text-2xl" role="img" aria-label={title}>
        {icon}
      </span>
      <h3 className="font-semibold">{title}</h3>
      <p className="text-sm text-muted-foreground">{description}</p>
    </div>
  )
}

export function Features() {
  return (
    <section className="px-4 py-16 md:py-24" id="features">
      <div className="mx-auto max-w-5xl">
        <div className="mb-12 flex flex-col items-center gap-3 text-center">
          <h2 className="text-3xl font-bold tracking-tight md:text-4xl">
            Everything you need to ship
          </h2>
          <p className="max-w-2xl text-muted-foreground">
            Stop rebuilding the same boilerplate. This template handles the
            infrastructure so you can start on your core product on day one.
          </p>
        </div>
        <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
          {FEATURES.map((feature) => (
            <FeatureCard key={feature.title} {...feature} />
          ))}
        </div>
      </div>
    </section>
  )
}

import { cn } from "@/lib/utils"

interface FaqItem {
  question: string
  answer: string
}

const FAQ_ITEMS: FaqItem[] = [
  {
    question: "What is this template?",
    answer:
      "A production-ready Next.js 16 SaaS starter. It includes authentication (NextAuth v5), billing (Stripe/ECPay via a PaymentProvider abstraction), 3-tier RBAC, Drizzle/Postgres, and shadcn/ui — so you can ship your product instead of rebuilding infrastructure.",
  },
  {
    question: "How do I install additional modules?",
    answer:
      "Run `npx shadcn@latest add @saas/<module-name>` from the `next-app/` directory. Each module ships with a `module.manifest.json` and a paired `install-*` skill that wires env vars, runs migrations, and walks you through any manual steps.",
  },
  {
    question: "Which payment gateways are supported?",
    answer:
      "The billing layer ships a `PaymentProvider` interface (E231). Stripe and ECPay adapters are implemented in dedicated modules. Additional gateways (TapPay, NewebPay) are reserved slots you can implement.",
  },
  {
    question: "Can I deploy to my own infrastructure?",
    answer:
      "Yes. The template ships a `Dockerfile` and a Zeabur config (`zbpack.json`), but any Node-compatible host works. Alembic-style migrations run on startup automatically.",
  },
  {
    question: "Is this open-source?",
    answer:
      "Yes. Fork it, extend it, use it commercially. Attribution is appreciated but not required.",
  },
]

interface FaqItemComponentProps extends FaqItem {
  className?: string
}

function FaqItemComponent({ question, answer, className }: FaqItemComponentProps) {
  return (
    <div className={cn("flex flex-col gap-2 border-b py-4 last:border-b-0", className)}>
      <h3 className="font-medium">{question}</h3>
      <p className="text-sm text-muted-foreground">{answer}</p>
    </div>
  )
}

export function Faq() {
  return (
    <section className="px-4 py-16 md:py-24" id="faq">
      <div className="mx-auto max-w-2xl">
        <div className="mb-10 flex flex-col items-center gap-3 text-center">
          <h2 className="text-3xl font-bold tracking-tight md:text-4xl">
            Frequently asked questions
          </h2>
          <p className="text-muted-foreground">
            Everything you need to know. Can&apos;t find what you&apos;re
            looking for? Open an issue on GitHub.
          </p>
        </div>
        <div>
          {FAQ_ITEMS.map((item) => (
            <FaqItemComponent key={item.question} {...item} />
          ))}
        </div>
      </div>
    </section>
  )
}

import Link from "next/link"

const FOOTER_LINKS = [
  { href: "#features", label: "Features" },
  { href: "#pricing", label: "Pricing" },
  { href: "#faq", label: "FAQ" },
  { href: "/login", label: "Sign in" },
  { href: "/register", label: "Register" },
]

export function MarketingFooter() {
  return (
    <footer className="border-t py-8">
      <div className="mx-auto max-w-5xl px-4">
        <div className="flex flex-col items-center gap-4 md:flex-row md:justify-between">
          <p className="text-sm text-muted-foreground">
            &copy; {new Date().getFullYear()} SaaS Template. All rights
            reserved.
          </p>
          <nav className="flex flex-wrap justify-center gap-4 text-sm text-muted-foreground">
            {FOOTER_LINKS.map(({ href, label }) => (
              <Link
                key={href}
                href={href}
                className="transition-colors hover:text-foreground"
              >
                {label}
              </Link>
            ))}
          </nav>
        </div>
      </div>
    </footer>
  )
}

import { MarketingFooter } from "@/components/marketing/marketing-footer"
import { MarketingNav } from "@/components/marketing/marketing-nav"

export default function MarketingLayout({
  children,
}: {
  children: React.ReactNode
}) {
  return (
    <div className="flex min-h-svh flex-col">
      <MarketingNav />
      <main className="flex-1">{children}</main>
      <MarketingFooter />
    </div>
  )
}

{
  "$schema": "../schema/module.manifest.schema.json",
  "id": "landing",
  "version": "1.0.0",
  "title": "Landing Page",
  "summary": "Public marketing landing page with Hero, Features, Pricing, FAQ, and CTA sections inside an app/(marketing)/ route group with shared nav and footer.",
  "registryDependencies": [
    "button",
    "badge",
    "card"
  ],
  "npmDependencies": {},
  "envVars": [],
  "dbTables": [],
  "db": {},
  "routes": [
    "(marketing)/layout.tsx",
    "(marketing)/page.tsx"
  ],
  "serverActions": [],
  "postInstall": [
    {
      "step": 1,
      "action": "manual",
      "description": "Remove or archive the existing app/page.tsx placeholder — the landing module owns the / route via app/(marketing)/page.tsx."
    },
    {
      "step": 2,
      "action": "manual",
      "description": "Customise branding: update the site name in components/marketing/marketing-nav.tsx and components/marketing/marketing-footer.tsx."
    },
    {
      "step": 3,
      "action": "manual",
      "description": "Update pricing tiers in components/marketing/pricing.tsx (DEFAULT_PRICING_TIERS) to match your billing plans once the billing adapter is live."
    },
    {
      "step": 4,
      "action": "command",
      "description": "Run typecheck and lint to verify no import errors.",
      "command": "pnpm typecheck && pnpm lint"
    },
    {
      "step": 5,
      "action": "docs",
      "description": "Read the landing module docs for theming and customisation guidance."
    }
  ],
  "docs": "/docs/modules/landing",
  "demo": {
    "path": "/",
    "iframeSrc": "http://localhost:3000/",
    "apiDemoPath": "/api/demo/landing"
  },
  "files": [
    {
      "path": "registry/landing/components/hero.tsx",
      "type": "registry:component",
      "target": "components/marketing/hero.tsx"
    },
    {
      "path": "registry/landing/components/features.tsx",
      "type": "registry:component",
      "target": "components/marketing/features.tsx"
    },
    {
      "path": "registry/landing/components/pricing.tsx",
      "type": "registry:component",
      "target": "components/marketing/pricing.tsx"
    },
    {
      "path": "registry/landing/components/faq.tsx",
      "type": "registry:component",
      "target": "components/marketing/faq.tsx"
    },
    {
      "path": "registry/landing/components/cta.tsx",
      "type": "registry:component",
      "target": "components/marketing/cta.tsx"
    },
    {
      "path": "registry/landing/components/marketing-nav.tsx",
      "type": "registry:component",
      "target": "components/marketing/marketing-nav.tsx"
    },
    {
      "path": "registry/landing/components/marketing-footer.tsx",
      "type": "registry:component",
      "target": "components/marketing/marketing-footer.tsx"
    },
    {
      "path": "registry/landing/app/(marketing)/layout.tsx",
      "type": "registry:page",
      "target": "app/(marketing)/layout.tsx"
    },
    {
      "path": "registry/landing/app/(marketing)/page.tsx",
      "type": "registry:page",
      "target": "app/(marketing)/page.tsx"
    },
    {
      "path": "registry/landing/module.manifest.json",
      "type": "registry:file",
      "target": "registry/landing/module.manifest.json"
    }
  ]
}
